window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-27516d7f2836253e"]={"versions": [{"id": "FIG-27516d7f2836253e", "releases": ["R3.2.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Fehlerfall- und Wirkungsanalyse im Kontext der AUTOSAR E2E-Library (End-to-End Communication Protection). Das Diagramm illustriert das Erkennungsverhalten eines E2E-Profils (Profil 1 / 1A mit Daten-ID-Liste bzw. Zähler-spezifischer DataID) bei einem Masquerading- bzw. Routingfehler, bei dem ein Empfänger fälschlicherweise Nachrichten eines fremden Senders empfängt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Tabelle gliedert sich in drei funktionale Abschnitte:</p>\n<ul class=\"fig-list\"><li><strong>Sender of B</strong>: Korrekter Sender für Botschaft B mit Spalten für Sende-Zähler (<em>Counter</em>, Werte 0 bis 15) und zugeordnete E2E-Daten-ID (<em>DataID</em>).\n</li><li><strong>Sender of E</strong>: Fremder Sender von Botschaft E mit Spalten für <em>Counter</em> und <em>DataID</em>.\n</li><li><strong>Receiver expects message B</strong>: Empfängerseite mit den Spalten:\n<ul class=\"fig-list\"><li><em>Counter</em>: Empfangener Zählerwert der Nachricht.\n</li><li><em>DataID used</em>: Vom empfangenen Datenstrom bzw. Fremdsender tatsächlich stammende / verwendete Daten-ID.\n</li><li><em>check</em>: Vergleichsoperator (<code>=</code> bzw. <code>≠</code>) zwischen verwendeter und erwarteter Daten-ID.\n</li><li><em>DataID expected</em>: Vom Empfänger für Botschaft B beim jeweiligen Zählerwert erwartete Daten-ID.\n</li><li><em>result of CRC-Check</em>: Ergebnisprüfung (<code>valid</code>, <code>erroneously undetected! (valid)</code>, <code>error detected (not valid)</code>).\n</li></ul>\n</li><li>Zusätzliche Annotationen: Markierung <code>here 1st routing error</code> mit horizontaler Trennlinie ab Counter 6.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Reguläre Übertragung (Counter 0 bis 5)</strong>: Sender B sendet Botschaft B. Der Empfänger erwartet Botschaft B; die im CRC eingebettete Daten-ID entspricht exakt der erwarteten Daten-ID (<code>DataID used = DataID expected</code>). Das Prüfergebnis ist jeweils <code>valid</code>.\n</li><li><strong>Eintritt des Routingfehlers (Counter 6)</strong>: Der Empfänger empfängt ab hier die Botschaft von Sender E statt B. Zufälligerweise stimmen die Daten-IDs beider Nachrichten bei Counter 6 überein (<code>18 = 18</code>). Der E2E-Schutzmechanismus schlägt bei dieser ersten fehlerhaften Nachricht nicht an (<code>erroneously undetected! (valid)</code>).\n</li><li><strong>Erkennung des Routingfehlers (ab Counter 7)</strong>: Bei Counter 7 weichen die Daten-IDs voneinander ab (Sender E nutzt <code>200</code>, Empfänger B erwartet <code>164</code>). Der Vergleich liefert Ungleichheit (<code>≠</code>), und der CRC-Check erkennt den Fehler zuverlässig (<code>error detected (not valid)</code>). Auch bei allen weiteren Zählerständen (8 bis 15 sowie im Folgezyklus bei Counter 5 mit <code>87 ≠ 123</code>) wird der Fehler detektiert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient dem normativen Nachweis der Erkennungssicherheit von Routingfehlern (Masquerade Detection) bei Verwendung dynamischer oder listenbasierter Daten-IDs (DataID-Array). Entwickler müssen beachten:</p>\n<ul class=\"fig-list\"><li>Eine statische Daten-ID könnte bei identischer ID-Vergabe oder Kollision dauerhaft unentdeckt bleiben.\n</li><li>Durch zählerabhängige Daten-ID-Listen wird sichergestellt, dass selbst bei einer zufälligen Übereinstimmung einer Daten-ID an einer Zählerposition (wie bei Counter 6) der Fehler spätestens mit der nachfolgenden Nachricht (Counter 7) durch Diskrepanz der Sequenzen zwingend erkannt wird.\n</li><li>Die Fehlererkennungslatenz bei Routing-Fehlern beträgt in diesem Auslegungsbeispiel maximal eine Nachricht.\n</li></ul>"}, {"id": "FIG-5dd984427e6c0800", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Fehlerfall- und Wirkungsanalyse im Kontext der AUTOSAR E2E-Library (End-to-End Communication Protection). Das Diagramm illustriert das Erkennungsverhalten eines E2E-Profils (Profil 1 / 1A mit Daten-ID-Liste bzw. Zähler-spezifischer DataID) bei einem Masquerading- bzw. Routingfehler, bei dem ein Empfänger fälschlicherweise Nachrichten eines fremden Senders empfängt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Tabelle gliedert sich in drei funktionale Abschnitte:</p>\n<ul class=\"fig-list\"><li><strong>Sender of B</strong>: Korrekter Sender für Botschaft B mit Spalten für Sende-Zähler (<em>Counter</em>, Werte 0 bis 15) und zugeordnete E2E-Daten-ID (<em>DataID</em>).\n</li><li><strong>Sender of E</strong>: Fremder Sender von Botschaft E mit Spalten für <em>Counter</em> und <em>DataID</em>.\n</li><li><strong>Receiver expects message B</strong>: Empfängerseite mit den Spalten:\n<ul class=\"fig-list\"><li><em>Counter</em>: Empfangener Zählerwert der Nachricht.\n</li><li><em>DataID used</em>: Vom empfangenen Datenstrom bzw. Fremdsender tatsächlich stammende / verwendete Daten-ID.\n</li><li><em>check</em>: Vergleichsoperator (<code>=</code> bzw. <code>≠</code>) zwischen verwendeter und erwarteter Daten-ID.\n</li><li><em>DataID expected</em>: Vom Empfänger für Botschaft B beim jeweiligen Zählerwert erwartete Daten-ID.\n</li><li><em>result of CRC-Check</em>: Ergebnisprüfung (<code>valid</code>, <code>erroneously undetected! (valid)</code>, <code>error detected (not valid)</code>).\n</li></ul>\n</li><li>Zusätzliche Annotationen: Markierung <code>here 1st routing error</code> mit horizontaler Trennlinie ab Counter 6.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Reguläre Übertragung (Counter 0 bis 5)</strong>: Sender B sendet Botschaft B. Der Empfänger erwartet Botschaft B; die im CRC eingebettete Daten-ID entspricht exakt der erwarteten Daten-ID (<code>DataID used = DataID expected</code>). Das Prüfergebnis ist jeweils <code>valid</code>.\n</li><li><strong>Eintritt des Routingfehlers (Counter 6)</strong>: Der Empfänger empfängt ab hier die Botschaft von Sender E statt B. Zufälligerweise stimmen die Daten-IDs beider Nachrichten bei Counter 6 überein (<code>18 = 18</code>). Der E2E-Schutzmechanismus schlägt bei dieser ersten fehlerhaften Nachricht nicht an (<code>erroneously undetected! (valid)</code>).\n</li><li><strong>Erkennung des Routingfehlers (ab Counter 7)</strong>: Bei Counter 7 weichen die Daten-IDs voneinander ab (Sender E nutzt <code>200</code>, Empfänger B erwartet <code>164</code>). Der Vergleich liefert Ungleichheit (<code>≠</code>), und der CRC-Check erkennt den Fehler zuverlässig (<code>error detected (not valid)</code>). Auch bei allen weiteren Zählerständen (8 bis 15 sowie im Folgezyklus bei Counter 5 mit <code>87 ≠ 123</code>) wird der Fehler detektiert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient dem normativen Nachweis der Erkennungssicherheit von Routingfehlern (Masquerade Detection) bei Verwendung dynamischer oder listenbasierter Daten-IDs (DataID-Array). Entwickler müssen beachten:</p>\n<ul class=\"fig-list\"><li>Eine statische Daten-ID könnte bei identischer ID-Vergabe oder Kollision dauerhaft unentdeckt bleiben.\n</li><li>Durch zählerabhängige Daten-ID-Listen wird sichergestellt, dass selbst bei einer zufälligen Übereinstimmung einer Daten-ID an einer Zählerposition (wie bei Counter 6) der Fehler spätestens mit der nachfolgenden Nachricht (Counter 7) durch Diskrepanz der Sequenzen zwingend erkannt wird.\n</li><li>Die Fehlererkennungslatenz bei Routing-Fehlern beträgt in diesem Auslegungsbeispiel maximal eine Nachricht.\n</li></ul>"}, {"id": "FIG-1dd815736cbc9116", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Fehlerfall- und Wirkungsanalyse im Kontext der AUTOSAR E2E-Library (End-to-End Communication Protection). Das Diagramm illustriert das Erkennungsverhalten eines E2E-Profils (Profil 1 / 1A mit Daten-ID-Liste bzw. Zähler-spezifischer DataID) bei einem Masquerading- bzw. Routingfehler, bei dem ein Empfänger fälschlicherweise Nachrichten eines fremden Senders empfängt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Tabelle gliedert sich in drei funktionale Abschnitte:</p>\n<ul class=\"fig-list\"><li><strong>Sender of B</strong>: Korrekter Sender für Botschaft B mit Spalten für Sende-Zähler (<em>Counter</em>, Werte 0 bis 15) und zugeordnete E2E-Daten-ID (<em>DataID</em>).\n</li><li><strong>Sender of E</strong>: Fremder Sender von Botschaft E mit Spalten für <em>Counter</em> und <em>DataID</em>.\n</li><li><strong>Receiver expects message B</strong>: Empfängerseite mit den Spalten:\n<ul class=\"fig-list\"><li><em>Counter</em>: Empfangener Zählerwert der Nachricht.\n</li><li><em>DataID used</em>: Vom empfangenen Datenstrom bzw. Fremdsender tatsächlich stammende / verwendete Daten-ID.\n</li><li><em>check</em>: Vergleichsoperator (<code>=</code> bzw. <code>≠</code>) zwischen verwendeter und erwarteter Daten-ID.\n</li><li><em>DataID expected</em>: Vom Empfänger für Botschaft B beim jeweiligen Zählerwert erwartete Daten-ID.\n</li><li><em>result of CRC-Check</em>: Ergebnisprüfung (<code>valid</code>, <code>erroneously undetected! (valid)</code>, <code>error detected (not valid)</code>).\n</li></ul>\n</li><li>Zusätzliche Annotationen: Markierung <code>here 1st routing error</code> mit horizontaler Trennlinie ab Counter 6.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Reguläre Übertragung (Counter 0 bis 5)</strong>: Sender B sendet Botschaft B. Der Empfänger erwartet Botschaft B; die im CRC eingebettete Daten-ID entspricht exakt der erwarteten Daten-ID (<code>DataID used = DataID expected</code>). Das Prüfergebnis ist jeweils <code>valid</code>.\n</li><li><strong>Eintritt des Routingfehlers (Counter 6)</strong>: Der Empfänger empfängt ab hier die Botschaft von Sender E statt B. Zufälligerweise stimmen die Daten-IDs beider Nachrichten bei Counter 6 überein (<code>18 = 18</code>). Der E2E-Schutzmechanismus schlägt bei dieser ersten fehlerhaften Nachricht nicht an (<code>erroneously undetected! (valid)</code>).\n</li><li><strong>Erkennung des Routingfehlers (ab Counter 7)</strong>: Bei Counter 7 weichen die Daten-IDs voneinander ab (Sender E nutzt <code>200</code>, Empfänger B erwartet <code>164</code>). Der Vergleich liefert Ungleichheit (<code>≠</code>), und der CRC-Check erkennt den Fehler zuverlässig (<code>error detected (not valid)</code>). Auch bei allen weiteren Zählerständen (8 bis 15 sowie im Folgezyklus bei Counter 5 mit <code>87 ≠ 123</code>) wird der Fehler detektiert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient dem normativen Nachweis der Erkennungssicherheit von Routingfehlern (Masquerade Detection) bei Verwendung dynamischer oder listenbasierter Daten-IDs (DataID-Array). Entwickler müssen beachten:</p>\n<ul class=\"fig-list\"><li>Eine statische Daten-ID könnte bei identischer ID-Vergabe oder Kollision dauerhaft unentdeckt bleiben.\n</li><li>Durch zählerabhängige Daten-ID-Listen wird sichergestellt, dass selbst bei einer zufälligen Übereinstimmung einer Daten-ID an einer Zählerposition (wie bei Counter 6) der Fehler spätestens mit der nachfolgenden Nachricht (Counter 7) durch Diskrepanz der Sequenzen zwingend erkannt wird.\n</li><li>Die Fehlererkennungslatenz bei Routing-Fehlern beträgt in diesem Auslegungsbeispiel maximal eine Nachricht.\n</li></ul>"}], "trans": [{"from": "FIG-27516d7f2836253e", "to": "FIG-5dd984427e6c0800", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Trennlinie bei Auftreten des Routingfehlers: gestrichelte Linie durch eine dickere, gröbere Strichelung (Dashed Line) ersetzt.\n</li></ul>"}, {"from": "FIG-5dd984427e6c0800", "to": "FIG-27516d7f2836253e", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Trennlinie bei Auftreten des Routingfehlers: Strichelung wieder auf die feinere, dünnere Punktierung/Strichelung zurückgesetzt.\n</li></ul>"}, {"from": "FIG-27516d7f2836253e", "to": "FIG-1dd815736cbc9116", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
